for (const pin of Object.values(MARKET_FEE_COPY_DOMAINS)) {
  for (const inverse of pin.inverses) Object.freeze(inverse);
  Object.freeze(pin.inverses); Object.freeze(pin);
}
Object.freeze(MARKET_FEE_COPY_DOMAINS);
const lf = text => text.replaceAll('\r\n', '\n');
const sha256 = text => crypto.createHash('sha256').update(text).digest('hex');
const blob = text => crypto.createHash('sha1').update('blob ' + Buffer.byteLength(text) + '\0').update(text).digest('hex');

export function assertMarketFeeCopySourceTransfer(file, input) {
  assert(Object.hasOwn(MARKET_FEE_COPY_DOMAINS, file), 'Unknown market fee-copy source domain');
  const text = Buffer.isBuffer(input) ? input.toString('utf8') : input;
  if (Buffer.isBuffer(input)) assert(Buffer.from(text).equals(input), 'Lossless UTF-8 source required');
  assert(typeof text === 'string', 'Market fee-copy source text required');
  assert(text === lf(text) || text === lf(text).replaceAll('\n', '\r\n'), 'Uniform whole LF/CRLF source required');
  const current = lf(text), pin = MARKET_FEE_COPY_DOMAINS[file];
  assert.equal(sha256(current), pin.currentSha256, 'Complete market fee-copy source drift: ' + file);
  assert.equal(blob(current), pin.currentBlob, 'Complete market fee-copy blob drift: ' + file);
  assert.equal(Buffer.byteLength(current), pin.currentBytes);
  let baselineText = current, previousEnd = -1;
  for (const inverse of pin.inverses) {
    assert(inverse.current.length > 0);
    assert.equal(current.split(inverse.current).length - 1, 1, 'Missing or duplicate market fee-copy inverse');
    const at = current.indexOf(inverse.current); assert(at >= previousEnd); previousEnd = at + inverse.current.length;
    assert.equal(baselineText.split(inverse.current).length - 1, 1);
    baselineText = baselineText.replace(inverse.current, () => inverse.baseline);
  }
  assert.equal(sha256(baselineText), pin.baselineSha256, 'Complete market fee-copy predecessor drift: ' + file);
  assert.equal(blob(baselineText), pin.baselineBlob);
  assert.equal(Buffer.byteLength(baselineText), pin.baselineBytes);
  return Object.freeze({ file, baselineText, predecessorRevision: MARKET_FEE_COPY_BASE_REVISION,
    sourceOnly: true, runtime: false, native: false });
}

export function marketFeeCopyHistoricalInput(file, input) {
  if (!Object.hasOwn(MARKET_FEE_COPY_DOMAINS, file)) return input;
  const buffer = Buffer.isBuffer(input), text = buffer ? input.toString('utf8') : input;
  if (buffer) assert(Buffer.from(text).equals(input), 'Lossless UTF-8 source required');
  if (typeof text !== 'string' || (text !== lf(text) && text !== lf(text).replaceAll('\n', '\r\n')))
    return input;
  if (sha256(lf(text)) !== MARKET_FEE_COPY_DOMAINS[file].currentSha256) return input;
  const baseline = assertMarketFeeCopySourceTransfer(file, text).baselineText;
  return buffer ? Buffer.from(baseline) : baseline;
}
